const listLadoQueueEntriesForTasks = `-- name: ListLadoQueueEntriesForTasks :many
SELECT id, task_id, project_id, plan_approval_id, policy_snapshot_id, enqueued_at,
    attempt_count, next_attempt_at, lease_token, claimed_at, lease_expires_at,
    waiting_reason, review_required_reason, blocked_reason, error_message,
    dispatched_session_id, failed_at, superseded_at, cancelled_at
FROM lado_queue_entries
WHERE task_id IN (/*SLICE:task_ids*/?)
ORDER BY task_id, enqueued_at DESC, id DESC
`

func (q *Queries) ListLadoQueueEntriesForTasks(ctx context.Context, taskIds []string) ([]LadoQueueEntry, error) {
	query := listLadoQueueEntriesForTasks
	var queryParams []interface{}
	if len(taskIds) > 0 {
		for _, v := range taskIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:task_ids*/?", strings.Repeat(",?", len(taskIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:task_ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LadoQueueEntry{}
	for rows.Next() {
		var i LadoQueueEntry
		if err := rows.Scan(
			&i.ID,
			&i.TaskID,
			&i.ProjectID,
			&i.PlanApprovalID,
			&i.PolicySnapshotID,
			&i.EnqueuedAt,
			&i.AttemptCount,
			&i.NextAttemptAt,
			&i.LeaseToken,
			&i.ClaimedAt,
			&i.LeaseExpiresAt,
			&i.WaitingReason,
			&i.ReviewRequiredReason,
			&i.BlockedReason,
			&i.ErrorMessage,
			&i.DispatchedSessionID,
			&i.FailedAt,
			&i.SupersededAt,
			&i.CancelledAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

